def run(data):
    r=subprocess.run([sys.executable,"-I","-B",PROG],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    assert r.returncode==0, r.stderr[:300]
    return json.loads(r.stdout)
bad=0
worst=0
for seed in range(60):
    rnd=random.Random(seed+900)
    Q=rnd.choice([1,2,3,4,8,16]); L=rnd.choice([1,2,4,8])
    U=rnd.choice([4,10,40,1000]); R=rnd.randint(1,min(16,U))
    borders=[0]+(sorted(rnd.sample(range(1,U),R-1)) if R>1 else [])+[U]
    n=rnd.choice([500,2000,5000])
    # adversarial: skew ranks toward low ranges and lanes unevenly
    style=rnd.choice(["uniform","lowrank","fewranks","onelane","ties"])
    packets=[]
    for i in range(n):
        if style=="uniform": rk=rnd.randrange(U)
        elif style=="lowrank": rk=rnd.randrange(min(U, max(1,U//R)))
        elif style=="fewranks": rk=rnd.choice([0, U//2, U-1])
        elif style=="ties": rk=rnd.choice([0,1,U-1])
        else: rk=rnd.randrange(U)
        ln = 0 if style=="onelane" else rnd.randrange(L)
        packets.append({"id":"c%d"%i,"lane":ln,"rank":rk})
    req={"mode":"burst","banks":Q,"lanes":L,"limit":U,"borders":borders,
         "start_bank":rnd.randrange(Q),"packets":packets}
    got=run(json.dumps(req).encode())
    schema.check_burst(got, req)
