        if rg["bound"]>0:
            ratio = rg["observed"]/rg["bound"]
            if ratio>worst: worst=ratio; print("worst ratio %.3f (obs %d bound %d) seed %d r %d style %s"%(ratio,rg["observed"],rg["bound"],seed,r,style))
