def main():
    try:
        data = sys.stdin.buffer.read(MAX_BYTES + 1)
    except Exception:
        _fail()
        return
    if len(data) > MAX_BYTES:
        _fail()
        return
    try:
        text = data.decode('utf-8')
    except UnicodeDecodeError:
        _fail()
        return
    try:
        obj = _parse_json(text)
        _check_depth(obj)
        result = _run(obj)
    except Invalid:
        _fail()
        return
    except (RecursionError, MemoryError):
        _fail()
        return
    except Exception:
        # Defensive: never emit diagnostics or a partial answer.
        _fail()
        return
    sys.stdout.write(json.dumps(result, separators=(',', ':')))
    sys.stdout.write('\n')
    sys.stdout.flush()
    return 0


if __name__ == '__main__':
